-- Roadmap Block 14 – Catalog Product Onboarding & Import UX
-- Customer forward migration matching the production migration contract.

create unique index if not exists products_instance_slug_uidx on public.products(instance_id, slug);
create unique index if not exists product_variants_instance_sku_uidx on public.product_variants(instance_id, sku);
create unique index if not exists products_id_instance_uidx on public.products(id, instance_id);
create table if not exists public.catalog_categories (id uuid primary key default gen_random_uuid(),instance_id uuid not null references public.webshop_instances(id) on delete cascade,name text not null check (char_length(trim(name)) between 1 and 120),slug text not null check (char_length(trim(slug)) between 1 and 120),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(instance_id, slug),unique(id, instance_id));
create table if not exists public.product_category_assignments (instance_id uuid not null references public.webshop_instances(id) on delete cascade,product_id uuid not null,category_id uuid not null,created_at timestamptz not null default now(),primary key(product_id, category_id),foreign key(product_id, instance_id) references public.products(id, instance_id) on delete cascade,foreign key(category_id, instance_id) references public.catalog_categories(id, instance_id) on delete cascade);
create index if not exists product_category_assignments_instance_idx on public.product_category_assignments(instance_id);
create index if not exists product_category_assignments_category_idx on public.product_category_assignments(category_id);
create table if not exists public.product_attributes (id uuid primary key default gen_random_uuid(),instance_id uuid not null references public.webshop_instances(id) on delete cascade,product_id uuid not null,name text not null check (char_length(trim(name)) between 1 and 120),value text not null check (char_length(trim(value)) between 1 and 500),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(product_id, name),foreign key(product_id, instance_id) references public.products(id, instance_id) on delete cascade);
create index if not exists product_attributes_instance_idx on public.product_attributes(instance_id);
create index if not exists product_attributes_product_idx on public.product_attributes(product_id);
create table if not exists public.product_media (id uuid primary key default gen_random_uuid(),instance_id uuid not null references public.webshop_instances(id) on delete cascade,product_id uuid not null,upload_key text not null check (char_length(upload_key) between 16 and 120),storage_bucket text not null default 'product-media',storage_path text not null check (char_length(storage_path) between 1 and 500),original_name text not null check (char_length(original_name) between 1 and 255),content_type text not null check (content_type in ('image/jpeg','image/png','image/webp','image/avif')),byte_size bigint not null check (byte_size > 0 and byte_size <= 8388608),alt_text text check (alt_text is null or char_length(alt_text) <= 300),sort_order integer not null default 0 check (sort_order >= 0 and sort_order <= 10000),created_at timestamptz not null default now(),unique(instance_id, upload_key),unique(instance_id, storage_path),foreign key(product_id, instance_id) references public.products(id, instance_id) on delete cascade);
create index if not exists product_media_product_idx on public.product_media(product_id, sort_order, created_at);
create table if not exists public.catalog_onboarding_batches (id uuid primary key default gen_random_uuid(),instance_id uuid not null references public.webshop_instances(id) on delete cascade,created_by uuid not null,source_type text not null check (source_type in ('manual','csv')),state text not null default 'preview' check (state in ('preview','applied')),idempotency_key text not null check (char_length(idempotency_key) between 16 and 120),payload_hash text not null check (payload_hash ~ '^[a-f0-9]{64}$'),preview_rows jsonb not null default '[]'::jsonb check (jsonb_typeof(preview_rows)='array'),apply_plan jsonb not null default '[]'::jsonb check (jsonb_typeof(apply_plan)='array'),error_count integer not null default 0 check (error_count >= 0),result jsonb,created_at timestamptz not null default now(),applied_at timestamptz,unique(instance_id, idempotency_key));
create index if not exists catalog_onboarding_batches_instance_created_idx on public.catalog_onboarding_batches(instance_id, created_at desc);
alter table public.catalog_categories enable row level security;alter table public.product_category_assignments enable row level security;alter table public.product_attributes enable row level security;alter table public.product_media enable row level security;alter table public.catalog_onboarding_batches enable row level security;
revoke all on public.catalog_categories, public.product_category_assignments,public.product_attributes, public.product_media, public.catalog_onboarding_batches from public, anon, authenticated;
grant select on public.catalog_categories, public.product_category_assignments,public.product_attributes, public.product_media to authenticated;
grant select, insert, update, delete on public.catalog_categories, public.product_category_assignments,public.product_attributes, public.product_media, public.catalog_onboarding_batches to service_role;
create policy catalog_categories_store_read on public.catalog_categories for select to authenticated using (public.can_read_store(instance_id));
create policy product_category_assignments_store_read on public.product_category_assignments for select to authenticated using (public.can_read_store(instance_id));
create policy product_attributes_store_read on public.product_attributes for select to authenticated using (public.can_read_store(instance_id));
create policy product_media_store_read on public.product_media for select to authenticated using (public.can_read_store(instance_id));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-media','product-media',true,8388608,array['image/jpeg','image/png','image/webp','image/avif']) on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;

create or replace function public.create_catalog_draft_v1(p_instance_id uuid,p_actor uuid,p_idempotency_key text,p_payload_hash text,p_product jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_org uuid;v_batch public.catalog_onboarding_batches%rowtype;v_product_id uuid;v_variant_id uuid;v_category_id uuid;v_category_name text;v_category_slug text;v_attr record;v_result jsonb; begin if p_instance_id is null or p_actor is null or nullif(trim(p_idempotency_key),'') is null then raise exception 'CATALOG_ONBOARDING_IDENTITY_REQUIRED';end if;if p_payload_hash !~ '^[a-f0-9]{64}$' or p_product is null or jsonb_typeof(p_product)<>'object' then raise exception 'CATALOG_ONBOARDING_PAYLOAD_INVALID';end if;if not public.can_manage_catalog(p_instance_id,p_actor) then raise exception 'CATALOG_PERMISSION_REQUIRED';end if;select organization_id into v_org from public.webshop_instances where id=p_instance_id;if v_org is null then raise exception 'WEBSHOP_INSTANCE_NOT_FOUND';end if;insert into public.catalog_onboarding_batches(instance_id,created_by,source_type,idempotency_key,payload_hash,preview_rows,apply_plan) values(p_instance_id,p_actor,'manual',p_idempotency_key,p_payload_hash,jsonb_build_array(p_product),jsonb_build_array(p_product)) on conflict(instance_id,idempotency_key) do nothing;select * into v_batch from public.catalog_onboarding_batches where instance_id=p_instance_id and idempotency_key=p_idempotency_key for update;if not found or v_batch.source_type<>'manual' then raise exception 'CATALOG_ONBOARDING_BATCH_INVALID';end if;if v_batch.payload_hash<>p_payload_hash then raise exception 'CATALOG_ONBOARDING_IDEMPOTENCY_CONFLICT';end if;if v_batch.state='applied' then return v_batch.result;end if;insert into public.products(instance_id,slug,name,short_description,description,active,audience,featured) values(p_instance_id,p_product->>'slug',p_product->>'name',nullif(p_product->>'shortDescription',''),nullif(p_product->>'description',''),false,'retail',false) returning id into v_product_id;insert into public.product_variants(instance_id,product_id,sku,label,net_price_huf,gross_price_huf,stock_quantity,active) values(p_instance_id,v_product_id,p_product->>'sku',coalesce(nullif(p_product->>'variantLabel',''),p_product->>'name'),(p_product->>'netPrice')::integer,(p_product->>'grossPrice')::integer,coalesce((p_product->>'stock')::integer,0),false) returning id into v_variant_id;v_category_name:=nullif(trim(p_product->>'category'),'');v_category_slug:=nullif(trim(p_product->>'categorySlug'),'');if v_category_name is not null and v_category_slug is not null then insert into public.catalog_categories(instance_id,name,slug) values(p_instance_id,v_category_name,v_category_slug) on conflict(instance_id,slug) do update set name=excluded.name,updated_at=now() returning id into v_category_id;insert into public.product_category_assignments(instance_id,product_id,category_id) values(p_instance_id,v_product_id,v_category_id) on conflict do nothing;end if;if jsonb_typeof(coalesce(p_product->'attributes','{}'::jsonb))='object' then for v_attr in select key,value from jsonb_each_text(coalesce(p_product->'attributes','{}'::jsonb)) loop if nullif(trim(v_attr.key),'') is not null and nullif(trim(v_attr.value),'') is not null then insert into public.product_attributes(instance_id,product_id,name,value) values(p_instance_id,v_product_id,trim(v_attr.key),trim(v_attr.value)) on conflict(product_id,name) do update set value=excluded.value,updated_at=now();end if;end loop;end if;v_result:=jsonb_build_object('productId',v_product_id,'variantId',v_variant_id,'draft',true);update public.catalog_onboarding_batches set state='applied',result=v_result,applied_at=now() where id=v_batch.id;insert into public.admin_audit_log(actor_user_id,action,entity_type,entity_id,organization_id,instance_id,summary,after_state,metadata) values(p_actor,'catalog.product_draft_created','product',v_product_id::text,v_org,p_instance_id,(p_product->>'name')||' termék piszkozat létrehozva',v_result,jsonb_build_object('audit_source','database_rpc','source','manual','batch_id',v_batch.id));return v_result;end;$$;
revoke all on function public.create_catalog_draft_v1(uuid,uuid,text,text,jsonb) from public,anon,authenticated;grant execute on function public.create_catalog_draft_v1(uuid,uuid,text,text,jsonb) to service_role;
create or replace function public.apply_catalog_onboarding_batch_v1(p_instance_id uuid,p_batch_id uuid,p_actor uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_org uuid;v_batch public.catalog_onboarding_batches%rowtype;v_row jsonb;v_product_id uuid;v_variant_id uuid;v_category_id uuid;v_category_name text;v_category_slug text;v_attr record;v_results jsonb:='[]'::jsonb; begin if p_instance_id is null or p_batch_id is null or p_actor is null then raise exception 'CATALOG_ONBOARDING_IDENTITY_REQUIRED';end if;if not public.can_manage_catalog(p_instance_id,p_actor) then raise exception 'CATALOG_PERMISSION_REQUIRED';end if;select organization_id into v_org from public.webshop_instances where id=p_instance_id;if v_org is null then raise exception 'WEBSHOP_INSTANCE_NOT_FOUND';end if;select * into v_batch from public.catalog_onboarding_batches where id=p_batch_id and instance_id=p_instance_id for update;if not found or v_batch.source_type<>'csv' then raise exception 'CATALOG_ONBOARDING_BATCH_INVALID';end if;if v_batch.created_by<>p_actor then raise exception 'CATALOG_ONBOARDING_BATCH_ACTOR_MISMATCH';end if;if v_batch.state='applied' then return coalesce(v_batch.result,'[]'::jsonb);end if;if jsonb_array_length(v_batch.apply_plan)=0 then raise exception 'CATALOG_ONBOARDING_EMPTY_PLAN';end if;for v_row in select value from jsonb_array_elements(v_batch.apply_plan) loop insert into public.products(instance_id,slug,name,short_description,description,active,audience,featured) values(p_instance_id,v_row->>'slug',v_row->>'name',nullif(v_row->>'shortDescription',''),nullif(v_row->>'description',''),false,'retail',false) returning id into v_product_id;insert into public.product_variants(instance_id,product_id,sku,label,net_price_huf,gross_price_huf,stock_quantity,active) values(p_instance_id,v_product_id,v_row->>'sku',coalesce(nullif(v_row->>'variantLabel',''),v_row->>'name'),(v_row->>'netPrice')::integer,(v_row->>'grossPrice')::integer,coalesce((v_row->>'stock')::integer,0),false) returning id into v_variant_id;v_category_name:=nullif(trim(v_row->>'category'),'');v_category_slug:=nullif(trim(v_row->>'categorySlug'),'');if v_category_name is not null and v_category_slug is not null then insert into public.catalog_categories(instance_id,name,slug) values(p_instance_id,v_category_name,v_category_slug) on conflict(instance_id,slug) do update set name=excluded.name,updated_at=now() returning id into v_category_id;insert into public.product_category_assignments(instance_id,product_id,category_id) values(p_instance_id,v_product_id,v_category_id) on conflict do nothing;end if;if jsonb_typeof(coalesce(v_row->'attributes','{}'::jsonb))='object' then for v_attr in select key,value from jsonb_each_text(coalesce(v_row->'attributes','{}'::jsonb)) loop if nullif(trim(v_attr.key),'') is not null and nullif(trim(v_attr.value),'') is not null then insert into public.product_attributes(instance_id,product_id,name,value) values(p_instance_id,v_product_id,trim(v_attr.key),trim(v_attr.value));end if;end loop;end if;v_results:=v_results||jsonb_build_array(jsonb_build_object('line',coalesce((v_row->>'line')::integer,0),'productId',v_product_id,'variantId',v_variant_id,'draft',true));end loop;update public.catalog_onboarding_batches set state='applied',result=v_results,applied_at=now() where id=v_batch.id;insert into public.admin_audit_log(actor_user_id,action,entity_type,entity_id,organization_id,instance_id,summary,after_state,metadata) values(p_actor,'catalog.csv_onboarding_applied','catalog_onboarding_batch',v_batch.id::text,v_org,p_instance_id,'CSV termék-onboarding alkalmazva: '||jsonb_array_length(v_results)||' piszkozat',v_results,jsonb_build_object('audit_source','database_rpc','source','csv','batch_id',v_batch.id,'error_count',v_batch.error_count));return v_results;end;$$;
revoke all on function public.apply_catalog_onboarding_batch_v1(uuid,uuid,uuid) from public,anon,authenticated;grant execute on function public.apply_catalog_onboarding_batch_v1(uuid,uuid,uuid) to service_role;
create or replace function public.record_product_media_v1(p_instance_id uuid,p_product_id uuid,p_actor uuid,p_upload_key text,p_storage_path text,p_original_name text,p_content_type text,p_byte_size bigint,p_alt_text text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_org uuid;v_existing public.product_media%rowtype;v_media public.product_media%rowtype; begin if not public.can_manage_catalog(p_instance_id,p_actor) then raise exception 'CATALOG_PERMISSION_REQUIRED';end if;if not exists(select 1 from public.products where id=p_product_id and instance_id=p_instance_id) then raise exception 'PRODUCT_NOT_FOUND';end if;select organization_id into v_org from public.webshop_instances where id=p_instance_id;select * into v_existing from public.product_media where instance_id=p_instance_id and upload_key=p_upload_key;if found then if v_existing.product_id<>p_product_id or v_existing.storage_path<>p_storage_path then raise exception 'PRODUCT_MEDIA_IDEMPOTENCY_CONFLICT';end if;return jsonb_build_object('mediaId',v_existing.id,'storagePath',v_existing.storage_path,'replayed',true);end if;insert into public.product_media(instance_id,product_id,upload_key,storage_path,original_name,content_type,byte_size,alt_text) values(p_instance_id,p_product_id,p_upload_key,p_storage_path,p_original_name,p_content_type,p_byte_size,nullif(trim(p_alt_text),'')) returning * into v_media;insert into public.admin_audit_log(actor_user_id,action,entity_type,entity_id,organization_id,instance_id,summary,after_state,metadata) values(p_actor,'catalog.product_media_added','product_media',v_media.id::text,v_org,p_instance_id,p_original_name||' termékmédia hozzáadva',to_jsonb(v_media),jsonb_build_object('audit_source','database_rpc','product_id',p_product_id));return jsonb_build_object('mediaId',v_media.id,'storagePath',v_media.storage_path,'replayed',false);end;$$;
revoke all on function public.record_product_media_v1(uuid,uuid,uuid,text,text,text,text,bigint,text) from public,anon,authenticated;grant execute on function public.record_product_media_v1(uuid,uuid,uuid,text,text,text,text,bigint,text) to service_role;
